// Package trail provides a git-native task queue for autonomous agent execution.
//
// Trails are task definitions stored in the entire/trails orphan branch.
// Execution state is tracked via lightweight git refs (no commits for state changes).
// The Trail Runner discovers open trails, claims them atomically, creates worktrees,
// and runs agents to complete the work.
package trail

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"regexp"
	"time"
)

// TrailID is a 12-character hex identifier for trails.
// This follows the same pattern as CheckpointID for consistency.
//
//nolint:recvcheck // UnmarshalJSON requires pointer receiver, others use value receiver
type TrailID string

// EmptyTrailID represents an unset or invalid trail ID.
const EmptyTrailID TrailID = ""

// trailIDPattern is the regex pattern for a valid trail ID: exactly 12 lowercase hex characters.
const trailIDPattern = `[0-9a-f]{12}`

// trailIDRegex validates the format: exactly 12 lowercase hex characters.
var trailIDRegex = regexp.MustCompile(`^` + trailIDPattern + `$`)

// NewTrailID creates a TrailID from a string, validating its format.
// Returns an error if the string is not a valid 12-character hex ID.
func NewTrailID(s string) (TrailID, error) {
	if err := ValidateTrailID(s); err != nil {
		return EmptyTrailID, err
	}
	return TrailID(s), nil
}

// MustTrailID creates a TrailID from a string, panicking if invalid.
// Use only when the ID is known to be valid (e.g., from trusted sources).
func MustTrailID(s string) TrailID {
	id, err := NewTrailID(s)
	if err != nil {
		panic(err)
	}
	return id
}

// GenerateTrailID creates a new random 12-character hex trail ID.
func GenerateTrailID() (TrailID, error) {
	bytes := make([]byte, 6) // 6 bytes = 12 hex chars
	if _, err := rand.Read(bytes); err != nil {
		return EmptyTrailID, fmt.Errorf("failed to generate random trail ID: %w", err)
	}
	return TrailID(hex.EncodeToString(bytes)), nil
}

// ValidateTrailID checks if a string is a valid trail ID format.
// Returns an error if invalid, nil if valid.
func ValidateTrailID(s string) error {
	if !trailIDRegex.MatchString(s) {
		return fmt.Errorf("invalid trail ID %q: must be 12 lowercase hex characters", s)
	}
	return nil
}

// String returns the trail ID as a string.
func (id TrailID) String() string {
	return string(id)
}

// IsEmpty returns true if the trail ID is empty or unset.
func (id TrailID) IsEmpty() bool {
	return id == EmptyTrailID
}

// Short returns the first 8 characters of the trail ID for display.
func (id TrailID) Short() string {
	if len(id) >= 8 {
		return string(id[:8])
	}
	return string(id)
}

// MarshalJSON implements json.Marshaler.
func (id TrailID) MarshalJSON() ([]byte, error) {
	data, err := json.Marshal(string(id))
	if err != nil {
		return nil, fmt.Errorf("failed to marshal trail ID: %w", err)
	}
	return data, nil
}

// UnmarshalJSON implements json.Unmarshaler with validation.
// Returns an error if the JSON string is not a valid 12-character hex ID.
// Empty strings are allowed and result in EmptyTrailID.
func (id *TrailID) UnmarshalJSON(data []byte) error {
	var s string
	if err := json.Unmarshal(data, &s); err != nil {
		return fmt.Errorf("failed to unmarshal trail ID: %w", err)
	}
	// Allow empty strings (represents unset trail ID)
	if s == "" {
		*id = EmptyTrailID
		return nil
	}
	if err := ValidateTrailID(s); err != nil {
		return err
	}
	*id = TrailID(s)
	return nil
}

// TrailState represents the execution state of a trail.
type TrailState string

const (
	// TrailStateOpen indicates the trail is available for execution.
	// No state refs exist for this trail.
	TrailStateOpen TrailState = "open"

	// TrailStateInProgress indicates the trail is being executed.
	// The claimed ref exists.
	TrailStateInProgress TrailState = "in_progress"

	// TrailStateCompleted indicates the trail finished successfully.
	// The completed ref exists.
	TrailStateCompleted TrailState = "completed"

	// TrailStateFailed indicates the trail execution failed.
	// The failed ref exists.
	TrailStateFailed TrailState = "failed"
)

// Trail represents a task definition stored in the entire/trails branch.
type Trail struct {
	// ID is the unique identifier for this trail.
	ID TrailID `json:"id"`

	// Title is a brief description of the task.
	Title string `json:"title"`

	// Description is the full task description/prompt for the agent.
	Description string `json:"description"`

	// Branch is the name of the branch to create for this trail's work.
	// If empty, defaults to "trail/<id>".
	Branch string `json:"branch"`

	// BaseBranch is the branch to create the work branch from.
	// If empty, defaults to the repository's default branch.
	BaseBranch string `json:"base_branch"`

	// AuthorID identifies who created this trail.
	AuthorID string `json:"author_id,omitempty"`

	// Assignees are optional user IDs that should work on this trail.
	Assignees []string `json:"assignees,omitempty"`

	// Labels are optional tags for categorization.
	Labels []string `json:"labels,omitempty"`

	// CreatedAt is when the trail was created.
	CreatedAt time.Time `json:"created_at"`

	// UpdatedAt is when the trail was last modified.
	UpdatedAt time.Time `json:"updated_at"`
}

// Validate checks if the trail has all required fields.
func (t *Trail) Validate() error {
	if t.ID.IsEmpty() {
		return fmt.Errorf("trail ID is required")
	}
	if t.Title == "" {
		return fmt.Errorf("trail title is required")
	}
	if t.Description == "" {
		return fmt.Errorf("trail description is required")
	}
	return nil
}

// GetBranch returns the branch name for this trail.
// Returns the configured Branch, or a default "trail/<id>" if not set.
func (t *Trail) GetBranch() string {
	if t.Branch != "" {
		return t.Branch
	}
	return "trail/" + t.ID.String()
}

// TrailWithState combines a trail with its current execution state.
type TrailWithState struct {
	Trail
	State TrailState `json:"state"`
}

package trail

import (
	"context"
	"encoding/json"
	"fmt"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/filemode"
	"github.com/go-git/go-git/v5/plumbing/object"
)

// TrailsBranchName is the orphan branch where trail definitions are stored.
const TrailsBranchName = "entire/trails"

// MetadataFileName is the name of the metadata file within each trail directory.
const MetadataFileName = "metadata.json"

// Store provides read/write access to trails stored in the entire/trails branch.
type Store struct {
	repo *git.Repository
}

// NewStore creates a new trail store for the given repository.
func NewStore(repo *git.Repository) *Store {
	return &Store{repo: repo}
}

// EnsureBranch creates the entire/trails orphan branch if it doesn't exist.
func (s *Store) EnsureBranch(ctx context.Context) error {
	_ = ctx // Reserved for future use

	refName := plumbing.NewBranchReferenceName(TrailsBranchName)
	_, err := s.repo.Reference(refName, true)
	if err == nil {
		return nil // Branch exists
	}

	// Create orphan branch with empty tree
	emptyTreeHash, err := checkpoint.BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
	if err != nil {
		return fmt.Errorf("failed to create empty tree: %w", err)
	}

	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize trails branch", authorName, authorEmail)
	if err != nil {
		return fmt.Errorf("failed to create initial commit: %w", err)
	}

	newRef := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to set branch reference: %w", err)
	}

	return nil
}

// Create writes a new trail to the entire/trails branch.
func (s *Store) Create(ctx context.Context, trail *Trail) error {
	if err := trail.Validate(); err != nil {
		return fmt.Errorf("invalid trail: %w", err)
	}

	// Ensure branch exists
	if err := s.EnsureBranch(ctx); err != nil {
		return err
	}

	// Get current branch tip and flatten tree
	ref, entries, err := s.getBranchEntries()
	if err != nil {
		return err
	}

	// Check if trail already exists
	trailPath := trail.ID.String() + "/" + MetadataFileName
	if _, exists := entries[trailPath]; exists {
		return fmt.Errorf("trail %s already exists", trail.ID)
	}

	// Set timestamps if not set
	now := time.Now().UTC()
	if trail.CreatedAt.IsZero() {
		trail.CreatedAt = now
	}
	if trail.UpdatedAt.IsZero() {
		trail.UpdatedAt = now
	}

	// Marshal trail to JSON
	trailJSON, err := jsonutil.MarshalIndentWithNewline(trail, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal trail: %w", err)
	}

	// Create blob
	blobHash, err := checkpoint.CreateBlobFromContent(s.repo, trailJSON)
	if err != nil {
		return fmt.Errorf("failed to create trail blob: %w", err)
	}

	// Add to entries
	entries[trailPath] = object.TreeEntry{
		Name: trailPath,
		Mode: filemode.Regular,
		Hash: blobHash,
	}

	// Build and commit
	newTreeHash, err := checkpoint.BuildTreeFromEntries(s.repo, entries)
	if err != nil {
		return fmt.Errorf("failed to build tree: %w", err)
	}

	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
	commitMsg := fmt.Sprintf("Create trail: %s\n\n%s", trail.ID.Short(), trail.Title)
	newCommitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, authorName, authorEmail)
	if err != nil {
		return fmt.Errorf("failed to create commit: %w", err)
	}

	refName := plumbing.NewBranchReferenceName(TrailsBranchName)
	newRef := plumbing.NewHashReference(refName, newCommitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to update branch reference: %w", err)
	}

	return nil
}

// Get retrieves a trail by ID from the entire/trails branch.
// Returns nil, nil if the trail doesn't exist.
func (s *Store) Get(ctx context.Context, id TrailID) (*Trail, error) {
	_ = ctx // Reserved for future use

	tree, err := s.getBranchTree()
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // No branch means no trail
	}

	// Try to get the trail directory
	trailTree, err := tree.Tree(id.String())
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // Trail directory not found
	}

	// Read metadata.json
	metadataFile, err := trailTree.File(MetadataFileName)
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // metadata.json not found
	}

	content, err := metadataFile.Contents()
	if err != nil {
		return nil, fmt.Errorf("failed to read trail metadata: %w", err)
	}

	var trail Trail
	if err := json.Unmarshal([]byte(content), &trail); err != nil {
		return nil, fmt.Errorf("failed to parse trail metadata: %w", err)
	}

	return &trail, nil
}

// List returns all trails from the entire/trails branch.
func (s *Store) List(ctx context.Context) ([]*Trail, error) {
	_ = ctx // Reserved for future use

	tree, err := s.getBranchTree()
	if err != nil {
		return []*Trail{}, nil //nolint:nilerr // No branch means empty list
	}

	var trails []*Trail

	// Each entry at root level should be a trail directory
	for _, entry := range tree.Entries {
		if entry.Mode != filemode.Dir {
			continue
		}

		// Validate that entry name is a valid trail ID
		if err := ValidateTrailID(entry.Name); err != nil {
			continue // Skip invalid directories
		}

		// Get the trail directory
		trailTree, err := s.repo.TreeObject(entry.Hash)
		if err != nil {
			continue
		}

		// Read metadata.json
		metadataFile, err := trailTree.File(MetadataFileName)
		if err != nil {
			continue
		}

		content, err := metadataFile.Contents()
		if err != nil {
			continue
		}

		var trail Trail
		if err := json.Unmarshal([]byte(content), &trail); err != nil {
			continue
		}

		trails = append(trails, &trail)
	}

	return trails, nil
}

// Update modifies an existing trail in the entire/trails branch.
func (s *Store) Update(ctx context.Context, trail *Trail) error {
	if err := trail.Validate(); err != nil {
		return fmt.Errorf("invalid trail: %w", err)
	}

	// Get current branch tip and flatten tree
	ref, entries, err := s.getBranchEntries()
	if err != nil {
		return err
	}

	// Check if trail exists
	trailPath := trail.ID.String() + "/" + MetadataFileName
	if _, exists := entries[trailPath]; !exists {
		return fmt.Errorf("trail %s not found", trail.ID)
	}

	// Update timestamp
	trail.UpdatedAt = time.Now().UTC()

	// Marshal trail to JSON
	trailJSON, err := jsonutil.MarshalIndentWithNewline(trail, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal trail: %w", err)
	}

	// Create blob
	blobHash, err := checkpoint.CreateBlobFromContent(s.repo, trailJSON)
	if err != nil {
		return fmt.Errorf("failed to create trail blob: %w", err)
	}

	// Update entry
	entries[trailPath] = object.TreeEntry{
		Name: trailPath,
		Mode: filemode.Regular,
		Hash: blobHash,
	}

	// Build and commit
	newTreeHash, err := checkpoint.BuildTreeFromEntries(s.repo, entries)
	if err != nil {
		return fmt.Errorf("failed to build tree: %w", err)
	}

	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
	commitMsg := fmt.Sprintf("Update trail: %s\n\n%s", trail.ID.Short(), trail.Title)
	newCommitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, authorName, authorEmail)
	if err != nil {
		return fmt.Errorf("failed to create commit: %w", err)
	}

	refName := plumbing.NewBranchReferenceName(TrailsBranchName)
	newRef := plumbing.NewHashReference(refName, newCommitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to update branch reference: %w", err)
	}

	return nil
}

// Delete removes a trail from the entire/trails branch.
func (s *Store) Delete(ctx context.Context, id TrailID) error {
	_ = ctx // Reserved for future use

	// Get current branch tip and flatten tree
	ref, entries, err := s.getBranchEntries()
	if err != nil {
		return err
	}

	// Find and remove all entries for this trail
	trailPrefix := id.String() + "/"
	found := false
	for key := range entries {
		if len(key) >= len(trailPrefix) && key[:len(trailPrefix)] == trailPrefix {
			delete(entries, key)
			found = true
		}
	}

	if !found {
		return fmt.Errorf("trail %s not found", id)
	}

	// Build and commit
	newTreeHash, err := checkpoint.BuildTreeFromEntries(s.repo, entries)
	if err != nil {
		return fmt.Errorf("failed to build tree: %w", err)
	}

	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
	commitMsg := fmt.Sprintf("Delete trail: %s", id.Short())
	newCommitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, authorName, authorEmail)
	if err != nil {
		return fmt.Errorf("failed to create commit: %w", err)
	}

	refName := plumbing.NewBranchReferenceName(TrailsBranchName)
	newRef := plumbing.NewHashReference(refName, newCommitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to update branch reference: %w", err)
	}

	return nil
}

// getBranchEntries returns the trails branch reference and flattened tree entries.
func (s *Store) getBranchEntries() (*plumbing.Reference, map[string]object.TreeEntry, error) {
	refName := plumbing.NewBranchReferenceName(TrailsBranchName)
	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, nil, fmt.Errorf("failed to get trails branch reference: %w", err)
	}

	parentCommit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, nil, fmt.Errorf("failed to get commit object: %w", err)
	}

	baseTree, err := parentCommit.Tree()
	if err != nil {
		return nil, nil, fmt.Errorf("failed to get commit tree: %w", err)
	}

	entries := make(map[string]object.TreeEntry)
	if err := checkpoint.FlattenTree(s.repo, baseTree, "", entries); err != nil {
		return nil, nil, err
	}

	return ref, entries, nil
}

// getBranchTree returns the tree object for the entire/trails branch.
func (s *Store) getBranchTree() (*object.Tree, error) {
	refName := plumbing.NewBranchReferenceName(TrailsBranchName)
	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, fmt.Errorf("trails branch not found: %w", err)
	}

	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, fmt.Errorf("failed to get commit object: %w", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		return nil, fmt.Errorf("failed to get commit tree: %w", err)
	}

	return tree, nil
}

// createCommit creates a commit with the given tree and parent.
func (s *Store) createCommit(treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) {
	commit := &object.Commit{
		TreeHash: treeHash,
		Message:  message,
		Author: object.Signature{
			Name:  authorName,
			Email: authorEmail,
			When:  time.Now(),
		},
		Committer: object.Signature{
			Name:  authorName,
			Email: authorEmail,
			When:  time.Now(),
		},
	}

	// Add parent if not zero (not an orphan commit)
	if parentHash != plumbing.ZeroHash {
		commit.ParentHashes = []plumbing.Hash{parentHash}
	}

	obj := s.repo.Storer.NewEncodedObject()
	if err := commit.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
	}

	hash, err := s.repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
	}

	return hash, nil
}

package trail

import (
	"context"
	"errors"
	"fmt"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
)

// RefPrefix is the prefix for all trail state refs.
const RefPrefix = "refs/entire/trails/"

// State ref suffixes
const (
	RefSuffixClaimed   = "/claimed"
	RefSuffixCompleted = "/completed"
	RefSuffixFailed    = "/failed"
)

// ErrAlreadyClaimed is returned when attempting to claim a trail that is already claimed.
var ErrAlreadyClaimed = errors.New("trail is already claimed")

// ErrNotClaimed is returned when attempting to complete/fail a trail that is not claimed.
var ErrNotClaimed = errors.New("trail is not claimed")

// StateManager manages trail execution state using git refs.
// State is tracked via lightweight refs (no commits for state changes):
//   - refs/entire/trails/<id>/claimed   -> branch HEAD when claimed
//   - refs/entire/trails/<id>/completed -> branch HEAD when done
//   - refs/entire/trails/<id>/failed    -> branch HEAD on error
type StateManager struct {
	repo *git.Repository
}

// NewStateManager creates a new state manager for the given repository.
func NewStateManager(repo *git.Repository) *StateManager {
	return &StateManager{repo: repo}
}

// GetState returns the current execution state of a trail.
func (m *StateManager) GetState(ctx context.Context, id TrailID) (TrailState, error) {
	_ = ctx // Reserved for future use

	// Check states in priority order: completed > failed > claimed > open
	if m.refExists(id, RefSuffixCompleted) {
		return TrailStateCompleted, nil
	}
	if m.refExists(id, RefSuffixFailed) {
		return TrailStateFailed, nil
	}
	if m.refExists(id, RefSuffixClaimed) {
		return TrailStateInProgress, nil
	}
	return TrailStateOpen, nil
}

// Claim atomically claims a trail for execution.
// Returns ErrAlreadyClaimed if the trail is already claimed.
// The ref points to the current HEAD of the work branch.
func (m *StateManager) Claim(ctx context.Context, id TrailID, branchHead plumbing.Hash) error {
	_ = ctx // Reserved for future use

	refName := m.refName(id, RefSuffixClaimed)

	// Check if already claimed
	if _, err := m.repo.Reference(refName, true); err == nil {
		return ErrAlreadyClaimed
	}

	// Create the claimed ref
	ref := plumbing.NewHashReference(refName, branchHead)
	if err := m.repo.Storer.SetReference(ref); err != nil {
		return fmt.Errorf("failed to create claimed ref: %w", err)
	}

	return nil
}

// Complete marks a trail as successfully completed.
// The ref points to the final HEAD of the work branch.
func (m *StateManager) Complete(ctx context.Context, id TrailID, branchHead plumbing.Hash) error {
	_ = ctx // Reserved for future use

	// Verify trail was claimed
	claimedRef := m.refName(id, RefSuffixClaimed)
	if _, err := m.repo.Reference(claimedRef, true); err != nil {
		return ErrNotClaimed
	}

	// Create completed ref
	completedRef := plumbing.NewHashReference(m.refName(id, RefSuffixCompleted), branchHead)
	if err := m.repo.Storer.SetReference(completedRef); err != nil {
		return fmt.Errorf("failed to create completed ref: %w", err)
	}

	// Remove claimed ref
	if err := m.repo.Storer.RemoveReference(claimedRef); err != nil {
		// Non-fatal: completed ref was created successfully
		return nil
	}

	return nil
}

// Fail marks a trail as failed.
// The ref points to the HEAD at time of failure.
func (m *StateManager) Fail(ctx context.Context, id TrailID, branchHead plumbing.Hash) error {
	_ = ctx // Reserved for future use

	// Verify trail was claimed
	claimedRef := m.refName(id, RefSuffixClaimed)
	if _, err := m.repo.Reference(claimedRef, true); err != nil {
		return ErrNotClaimed
	}

	// Create failed ref
	failedRef := plumbing.NewHashReference(m.refName(id, RefSuffixFailed), branchHead)
	if err := m.repo.Storer.SetReference(failedRef); err != nil {
		return fmt.Errorf("failed to create failed ref: %w", err)
	}

	// Remove claimed ref
	if err := m.repo.Storer.RemoveReference(claimedRef); err != nil {
		// Non-fatal: failed ref was created successfully
		return nil
	}

	return nil
}

// Release releases a claimed trail without marking it completed or failed.
// This allows another runner to pick up the trail.
func (m *StateManager) Release(ctx context.Context, id TrailID) error {
	_ = ctx // Reserved for future use

	claimedRef := m.refName(id, RefSuffixClaimed)
	if _, err := m.repo.Reference(claimedRef, true); err != nil {
		return ErrNotClaimed
	}

	if err := m.repo.Storer.RemoveReference(claimedRef); err != nil {
		return fmt.Errorf("failed to remove claimed ref: %w", err)
	}

	return nil
}

// Reset removes all state refs for a trail, returning it to open state.
// This is useful for retrying a failed trail.
func (m *StateManager) Reset(ctx context.Context, id TrailID) error {
	_ = ctx // Reserved for future use

	// Remove all state refs
	for _, suffix := range []string{RefSuffixClaimed, RefSuffixCompleted, RefSuffixFailed} {
		refName := m.refName(id, suffix)
		if _, err := m.repo.Reference(refName, true); err == nil {
			if removeErr := m.repo.Storer.RemoveReference(refName); removeErr != nil {
				return fmt.Errorf("failed to remove ref %s: %w", refName, removeErr)
			}
		}
	}

	return nil
}

// GetClaimedRef returns the commit hash that the claimed ref points to.
// Returns plumbing.ZeroHash if not claimed.
func (m *StateManager) GetClaimedRef(ctx context.Context, id TrailID) (plumbing.Hash, error) {
	_ = ctx // Reserved for future use

	ref, err := m.repo.Reference(m.refName(id, RefSuffixClaimed), true)
	if err != nil {
		return plumbing.ZeroHash, nil //nolint:nilerr // No ref means not claimed
	}
	return ref.Hash(), nil
}

// GetCompletedRef returns the commit hash that the completed ref points to.
// Returns plumbing.ZeroHash if not completed.
func (m *StateManager) GetCompletedRef(ctx context.Context, id TrailID) (plumbing.Hash, error) {
	_ = ctx // Reserved for future use

	ref, err := m.repo.Reference(m.refName(id, RefSuffixCompleted), true)
	if err != nil {
		return plumbing.ZeroHash, nil //nolint:nilerr // No ref means not completed
	}
	return ref.Hash(), nil
}

// GetFailedRef returns the commit hash that the failed ref points to.
// Returns plumbing.ZeroHash if not failed.
func (m *StateManager) GetFailedRef(ctx context.Context, id TrailID) (plumbing.Hash, error) {
	_ = ctx // Reserved for future use

	ref, err := m.repo.Reference(m.refName(id, RefSuffixFailed), true)
	if err != nil {
		return plumbing.ZeroHash, nil //nolint:nilerr // No ref means not failed
	}
	return ref.Hash(), nil
}

// refName returns the full reference name for a trail state.
func (m *StateManager) refName(id TrailID, suffix string) plumbing.ReferenceName {
	return plumbing.ReferenceName(RefPrefix + id.String() + suffix)
}

// refExists checks if a ref exists for the given trail and suffix.
func (m *StateManager) refExists(id TrailID, suffix string) bool {
	_, err := m.repo.Reference(m.refName(id, suffix), true)
	return err == nil
}

package trail

import (
	"context"
	"sort"

	"github.com/go-git/go-git/v5"
)

// Discovery provides methods to discover and filter trails.
type Discovery struct {
	store *Store
	state *StateManager
}

// NewDiscovery creates a new discovery instance.
func NewDiscovery(repo *git.Repository) *Discovery {
	return &Discovery{
		store: NewStore(repo),
		state: NewStateManager(repo),
	}
}

// ListFilter specifies filtering options for listing trails.
type ListFilter struct {
	// States filters to trails matching any of these states.
	// If empty, returns all trails.
	States []TrailState

	// Labels filters to trails having all of these labels.
	Labels []string

	// Assignees filters to trails assigned to any of these users.
	Assignees []string
}

// ListWithState returns all trails with their current execution state.
func (d *Discovery) ListWithState(ctx context.Context, filter *ListFilter) ([]TrailWithState, error) {
	trails, err := d.store.List(ctx)
	if err != nil {
		return nil, err
	}

	var result []TrailWithState

	for _, trail := range trails {
		state, err := d.state.GetState(ctx, trail.ID)
		if err != nil {
			// Skip trails we can't get state for
			continue
		}

		// Apply state filter
		if filter != nil && len(filter.States) > 0 {
			if !containsState(filter.States, state) {
				continue
			}
		}

		// Apply label filter (AND logic - must have all labels)
		if filter != nil && len(filter.Labels) > 0 {
			if !hasAllLabels(trail.Labels, filter.Labels) {
				continue
			}
		}

		// Apply assignee filter (OR logic - any assignee matches)
		if filter != nil && len(filter.Assignees) > 0 {
			if !hasAnyAssignee(trail.Assignees, filter.Assignees) {
				continue
			}
		}

		result = append(result, TrailWithState{
			Trail: *trail,
			State: state,
		})
	}

	// Sort by created date (newest first)
	sort.Slice(result, func(i, j int) bool {
		return result[i].CreatedAt.After(result[j].CreatedAt)
	})

	return result, nil
}

// FindOpen returns trails that are available for execution.
func (d *Discovery) FindOpen(ctx context.Context) ([]TrailWithState, error) {
	return d.ListWithState(ctx, &ListFilter{
		States: []TrailState{TrailStateOpen},
	})
}

// FindInProgress returns trails that are currently being executed.
func (d *Discovery) FindInProgress(ctx context.Context) ([]TrailWithState, error) {
	return d.ListWithState(ctx, &ListFilter{
		States: []TrailState{TrailStateInProgress},
	})
}

// FindCompleted returns trails that have been successfully completed.
func (d *Discovery) FindCompleted(ctx context.Context) ([]TrailWithState, error) {
	return d.ListWithState(ctx, &ListFilter{
		States: []TrailState{TrailStateCompleted},
	})
}

// FindFailed returns trails that failed during execution.
func (d *Discovery) FindFailed(ctx context.Context) ([]TrailWithState, error) {
	return d.ListWithState(ctx, &ListFilter{
		States: []TrailState{TrailStateFailed},
	})
}

// GetWithState retrieves a single trail with its current state.
func (d *Discovery) GetWithState(ctx context.Context, id TrailID) (*TrailWithState, error) {
	trail, err := d.store.Get(ctx, id)
	if err != nil {
		return nil, err
	}
	if trail == nil {
		return nil, nil //nolint:nilnil // Trail not found
	}

	state, err := d.state.GetState(ctx, trail.ID)
	if err != nil {
		return nil, err
	}

	return &TrailWithState{
		Trail: *trail,
		State: state,
	}, nil
}

// containsState checks if a state is in the list of states.
func containsState(states []TrailState, state TrailState) bool {
	for _, s := range states {
		if s == state {
			return true
		}
	}
	return false
}

// hasAllLabels checks if the trail has all the required labels.
func hasAllLabels(trailLabels, requiredLabels []string) bool {
	labelSet := make(map[string]bool)
	for _, l := range trailLabels {
		labelSet[l] = true
	}
	for _, l := range requiredLabels {
		if !labelSet[l] {
			return false
		}
	}
	return true
}

// hasAnyAssignee checks if the trail has any of the specified assignees.
func hasAnyAssignee(trailAssignees, filterAssignees []string) bool {
	assigneeSet := make(map[string]bool)
	for _, a := range trailAssignees {
		assigneeSet[a] = true
	}
	for _, a := range filterAssignees {
		if assigneeSet[a] {
			return true
		}
	}
	return false
}

package trail

import (
	"context"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// WorktreeDir is the directory where trail worktrees are created.
const WorktreeDir = ".worktrees"

// WorktreeManager manages git worktrees for trail execution.
type WorktreeManager struct {
	repoRoot string
}

// NewWorktreeManager creates a new worktree manager.
// The repoRoot should be the path to the main git repository.
func NewWorktreeManager(repoRoot string) *WorktreeManager {
	return &WorktreeManager{repoRoot: repoRoot}
}

// WorktreePath returns the path where a trail's worktree should be created.
func (m *WorktreeManager) WorktreePath(id TrailID) string {
	return filepath.Join(m.repoRoot, WorktreeDir, "trail-"+id.String())
}

// Create creates a new git worktree for a trail.
// If the branch doesn't exist, it will be created from baseBranch.
func (m *WorktreeManager) Create(ctx context.Context, id TrailID, branch, baseBranch string) (string, error) {
	worktreePath := m.WorktreePath(id)

	// Ensure the worktrees directory exists
	worktreesDir := filepath.Join(m.repoRoot, WorktreeDir)
	if err := os.MkdirAll(worktreesDir, 0o755); err != nil {
		return "", fmt.Errorf("failed to create worktrees directory: %w", err)
	}

	// Check if worktree already exists
	if _, err := os.Stat(worktreePath); err == nil {
		return worktreePath, nil // Already exists
	}

	// Check if the branch exists
	branchExists, err := m.branchExists(ctx, branch)
	if err != nil {
		return "", fmt.Errorf("failed to check branch existence: %w", err)
	}

	if branchExists {
		// Worktree for existing branch
		cmd := exec.CommandContext(ctx, "git", "worktree", "add", worktreePath, branch)
		cmd.Dir = m.repoRoot
		if output, err := cmd.CombinedOutput(); err != nil {
			return "", fmt.Errorf("failed to create worktree: %s: %w", strings.TrimSpace(string(output)), err)
		}
	} else {
		// Create new branch from base
		if baseBranch == "" {
			// Get default branch
			baseBranch, err = m.getDefaultBranch(ctx)
			if err != nil {
				return "", fmt.Errorf("failed to determine base branch: %w", err)
			}
		}

		// Create worktree with new branch
		cmd := exec.CommandContext(ctx, "git", "worktree", "add", "-b", branch, worktreePath, baseBranch)
		cmd.Dir = m.repoRoot
		if output, err := cmd.CombinedOutput(); err != nil {
			return "", fmt.Errorf("failed to create worktree with new branch: %s: %w", strings.TrimSpace(string(output)), err)
		}
	}

	return worktreePath, nil
}

// Remove removes a trail's worktree.
func (m *WorktreeManager) Remove(ctx context.Context, id TrailID) error {
	worktreePath := m.WorktreePath(id)

	// Check if worktree exists
	if _, err := os.Stat(worktreePath); os.IsNotExist(err) {
		return nil // Already removed
	}

	// Remove the worktree
	cmd := exec.CommandContext(ctx, "git", "worktree", "remove", "--force", worktreePath)
	cmd.Dir = m.repoRoot
	if output, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("failed to remove worktree: %s: %w", strings.TrimSpace(string(output)), err)
	}

	return nil
}

// Exists checks if a worktree exists for the given trail.
func (m *WorktreeManager) Exists(id TrailID) bool {
	worktreePath := m.WorktreePath(id)
	_, err := os.Stat(worktreePath)
	return err == nil
}

// GetCurrentBranch returns the current branch name in a worktree.
func (m *WorktreeManager) GetCurrentBranch(ctx context.Context, id TrailID) (string, error) {
	worktreePath := m.WorktreePath(id)

	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--abbrev-ref", "HEAD")
	cmd.Dir = worktreePath
	output, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("failed to get current branch: %w", err)
	}

	return strings.TrimSpace(string(output)), nil
}

// GetHeadCommit returns the HEAD commit hash in a worktree.
func (m *WorktreeManager) GetHeadCommit(ctx context.Context, id TrailID) (string, error) {
	worktreePath := m.WorktreePath(id)

	cmd := exec.CommandContext(ctx, "git", "rev-parse", "HEAD")
	cmd.Dir = worktreePath
	output, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("failed to get HEAD commit: %w", err)
	}

	return strings.TrimSpace(string(output)), nil
}

// branchExists checks if a branch exists in the repository.
func (m *WorktreeManager) branchExists(ctx context.Context, branch string) (bool, error) {
	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--verify", "refs/heads/"+branch)
	cmd.Dir = m.repoRoot
	if err := cmd.Run(); err != nil {
		// Branch doesn't exist
		return false, nil
	}
	return true, nil
}

// getDefaultBranch returns the repository's default branch name.
func (m *WorktreeManager) getDefaultBranch(ctx context.Context) (string, error) {
	// Try to get the default branch from origin
	cmd := exec.CommandContext(ctx, "git", "symbolic-ref", "refs/remotes/origin/HEAD")
	cmd.Dir = m.repoRoot
	if output, err := cmd.Output(); err == nil {
		ref := strings.TrimSpace(string(output))
		// Extract branch name from refs/remotes/origin/main
		parts := strings.Split(ref, "/")
		if len(parts) > 0 {
			return parts[len(parts)-1], nil
		}
	}

	// Fall back to checking common default branch names
	for _, branch := range []string{"main", "master"} {
		exists, err := m.branchExists(ctx, branch)
		if err != nil {
			continue
		}
		if exists {
			return branch, nil
		}
	}

	return "", fmt.Errorf("could not determine default branch")
}

// List returns all trail worktrees.
func (m *WorktreeManager) List() ([]string, error) {
	worktreesDir := filepath.Join(m.repoRoot, WorktreeDir)

	entries, err := os.ReadDir(worktreesDir)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, fmt.Errorf("failed to read worktrees directory: %w", err)
	}

	var worktrees []string
	for _, entry := range entries {
		if entry.IsDir() && strings.HasPrefix(entry.Name(), "trail-") {
			worktrees = append(worktrees, filepath.Join(worktreesDir, entry.Name()))
		}
	}

	return worktrees, nil
}

// EnsureWorktreesIgnored ensures the .worktrees directory is in .gitignore.
func EnsureWorktreesIgnored(repoRoot string) error {
	gitignorePath := filepath.Join(repoRoot, ".gitignore")

	// Read existing .gitignore
	content, err := os.ReadFile(gitignorePath)
	if err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("failed to read .gitignore: %w", err)
	}

	// Check if already ignored
	lines := strings.Split(string(content), "\n")
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == WorktreeDir || trimmed == WorktreeDir+"/" {
			return nil // Already ignored
		}
	}

	// Add to .gitignore
	var newContent string
	if len(content) > 0 && !strings.HasSuffix(string(content), "\n") {
		newContent = string(content) + "\n" + WorktreeDir + "/\n"
	} else {
		newContent = string(content) + WorktreeDir + "/\n"
	}

	if err := os.WriteFile(gitignorePath, []byte(newContent), 0o644); err != nil {
		return fmt.Errorf("failed to update .gitignore: %w", err)
	}

	return nil
}

// GetRepoRoot returns the repository root, using the paths package.
func GetRepoRoot() (string, error) {
	return paths.RepoRoot()
}

package trail

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"os/exec"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/logging"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
)

// RunnerConfig holds configuration for the trail runner.
type RunnerConfig struct {
	// PollInterval is how often to check for new trails in daemon mode.
	PollInterval time.Duration

	// MaxConcurrent is the maximum number of trails to run concurrently.
	// Currently only 1 is supported.
	MaxConcurrent int

	// Daemon enables continuous polling mode.
	Daemon bool

	// Agent is the agent CLI to use (e.g., "claude").
	Agent string

	// Model is the optional model override for the agent.
	Model string

	// Timeout is the maximum time to wait for a single trail execution.
	Timeout time.Duration

	// DryRun prevents actual execution, just prints what would be done.
	DryRun bool
}

// DefaultRunnerConfig returns the default runner configuration.
func DefaultRunnerConfig() RunnerConfig {
	return RunnerConfig{
		PollInterval:  30 * time.Second,
		MaxConcurrent: 1,
		Daemon:        false,
		Agent:         "claude",
		Model:         "",
		Timeout:       30 * time.Minute,
		DryRun:        false,
	}
}

// Runner executes trails by discovering open tasks, claiming them,
// creating worktrees, running agents, and updating state.
type Runner struct {
	repo      *git.Repository
	repoRoot  string
	store     *Store
	state     *StateManager
	discovery *Discovery
	worktree  *WorktreeManager
	config    RunnerConfig
}

// NewRunner creates a new trail runner.
func NewRunner(repo *git.Repository, repoRoot string, config RunnerConfig) *Runner {
	return &Runner{
		repo:      repo,
		repoRoot:  repoRoot,
		store:     NewStore(repo),
		state:     NewStateManager(repo),
		discovery: NewDiscovery(repo),
		worktree:  NewWorktreeManager(repoRoot),
		config:    config,
	}
}

// RunResult holds the result of running a single trail.
type RunResult struct {
	Trail    *Trail
	Success  bool
	Output   string
	Error    error
	Duration time.Duration
}

// Start runs the trail runner in daemon mode, continuously polling for new trails.
func (r *Runner) Start(ctx context.Context) error {
	logging.Info(ctx, "trail runner started",
		slog.Duration("poll_interval", r.config.PollInterval),
		slog.Bool("daemon", r.config.Daemon),
	)

	for {
		// Run one iteration
		results, err := r.RunOnce(ctx)
		if err != nil {
			logging.Error(ctx, "runner iteration failed", slog.String("error", err.Error()))
		}

		for _, result := range results {
			if result.Success {
				logging.Info(ctx, "trail completed successfully",
					slog.String("trail_id", result.Trail.ID.String()),
					slog.Duration("duration", result.Duration),
				)
			} else {
				logging.Error(ctx, "trail failed",
					slog.String("trail_id", result.Trail.ID.String()),
					slog.String("error", result.Error.Error()),
				)
			}
		}

		if !r.config.Daemon {
			return nil
		}

		// Wait before next poll
		select {
		case <-ctx.Done():
			logging.Info(ctx, "trail runner stopping")
			return ctx.Err()
		case <-time.After(r.config.PollInterval):
			// Continue to next iteration
		}
	}
}

// RunOnce performs a single iteration: find open trails and run them.
func (r *Runner) RunOnce(ctx context.Context) ([]RunResult, error) {
	// Find open trails
	openTrails, err := r.discovery.FindOpen(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to find open trails: %w", err)
	}

	if len(openTrails) == 0 {
		logging.Debug(ctx, "no open trails found")
		return nil, nil
	}

	logging.Info(ctx, "found open trails", slog.Int("count", len(openTrails)))

	var results []RunResult

	// Run trails up to max concurrent (currently only 1)
	for i := 0; i < min(len(openTrails), r.config.MaxConcurrent); i++ {
		trail := openTrails[i].Trail
		result := r.RunTrail(ctx, &trail)
		results = append(results, result)
	}

	return results, nil
}

// RunTrail executes a single trail.
func (r *Runner) RunTrail(ctx context.Context, trail *Trail) RunResult {
	start := time.Now()
	result := RunResult{Trail: trail}

	ctx = logging.WithComponent(ctx, "trail-runner")

	logging.Info(ctx, "starting trail execution",
		slog.String("trail_id", trail.ID.String()),
		slog.String("title", trail.Title),
	)

	if r.config.DryRun {
		logging.Info(ctx, "dry run - skipping execution")
		result.Success = true
		result.Output = "dry run"
		result.Duration = time.Since(start)
		return result
	}

	// Create worktree and get initial branch head
	worktreePath, branchHead, err := r.setupWorktree(ctx, trail)
	if err != nil {
		result.Error = fmt.Errorf("failed to setup worktree: %w", err)
		result.Duration = time.Since(start)
		return result
	}

	// Claim the trail
	if err := r.state.Claim(ctx, trail.ID, branchHead); err != nil {
		if errors.Is(err, ErrAlreadyClaimed) {
			logging.Info(ctx, "trail already claimed, skipping",
				slog.String("trail_id", trail.ID.String()),
			)
		}
		result.Error = err
		result.Duration = time.Since(start)
		// Clean up worktree if we couldn't claim
		_ = r.worktree.Remove(ctx, trail.ID)
		return result
	}

	// Run the agent
	output, agentErr := r.runAgent(ctx, trail, worktreePath)
	result.Output = output

	// Get final branch head
	finalHead, _ := r.worktree.GetHeadCommit(ctx, trail.ID)
	finalHeadHash := plumbing.NewHash(finalHead)
	if finalHeadHash.IsZero() {
		finalHeadHash = branchHead
	}

	// Update state based on result
	if agentErr != nil {
		result.Error = agentErr
		result.Success = false
		if err := r.state.Fail(ctx, trail.ID, finalHeadHash); err != nil {
			logging.Error(ctx, "failed to mark trail as failed",
				slog.String("trail_id", trail.ID.String()),
				slog.String("error", err.Error()),
			)
		}
	} else {
		result.Success = true
		if err := r.state.Complete(ctx, trail.ID, finalHeadHash); err != nil {
			logging.Error(ctx, "failed to mark trail as completed",
				slog.String("trail_id", trail.ID.String()),
				slog.String("error", err.Error()),
			)
		}
	}

	// Clean up worktree
	if err := r.worktree.Remove(ctx, trail.ID); err != nil {
		logging.Warn(ctx, "failed to remove worktree",
			slog.String("trail_id", trail.ID.String()),
			slog.String("error", err.Error()),
		)
	}

	result.Duration = time.Since(start)

	logging.Info(ctx, "trail execution finished",
		slog.String("trail_id", trail.ID.String()),
		slog.Bool("success", result.Success),
		slog.Duration("duration", result.Duration),
	)

	return result
}

// setupWorktree creates a worktree for the trail and returns the path and branch head.
func (r *Runner) setupWorktree(ctx context.Context, trail *Trail) (string, plumbing.Hash, error) {
	branch := trail.GetBranch()

	// Ensure .worktrees is in .gitignore
	if err := EnsureWorktreesIgnored(r.repoRoot); err != nil {
		logging.Warn(ctx, "failed to ensure worktrees ignored",
			slog.String("error", err.Error()),
		)
	}

	// Create the worktree
	worktreePath, err := r.worktree.Create(ctx, trail.ID, branch, trail.BaseBranch)
	if err != nil {
		return "", plumbing.ZeroHash, err
	}

	// Get the branch head
	headCommit, err := r.worktree.GetHeadCommit(ctx, trail.ID)
	if err != nil {
		return "", plumbing.ZeroHash, fmt.Errorf("failed to get branch head: %w", err)
	}

	return worktreePath, plumbing.NewHash(headCommit), nil
}

// runAgent executes the agent CLI with the trail description.
func (r *Runner) runAgent(ctx context.Context, trail *Trail, worktreePath string) (string, error) {
	// Build the prompt from trail description
	prompt := trail.Description

	// Build command arguments
	args := []string{}

	// Add model if specified
	if r.config.Model != "" {
		args = append(args, "--model", r.config.Model)
	}

	// Add prompt
	args = append(args, "-p", prompt)

	// Create context with timeout
	if r.config.Timeout > 0 {
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, r.config.Timeout)
		defer cancel()
	}

	logging.Debug(ctx, "running agent",
		slog.String("agent", r.config.Agent),
		slog.String("worktree", worktreePath),
	)

	//nolint:gosec // args are constructed from trusted config
	cmd := exec.CommandContext(ctx, r.config.Agent, args...)
	cmd.Dir = worktreePath
	cmd.Env = append(os.Environ(),
		// Ensure entire hooks are enabled in the worktree
		"ENTIRE_ENABLED=1",
	)

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()

	output := stdout.String()
	if stderr.Len() > 0 {
		if output != "" {
			output += "\n"
		}
		output += stderr.String()
	}

	if err != nil {
		if ctx.Err() == context.DeadlineExceeded {
			return output, fmt.Errorf("agent timed out after %s", r.config.Timeout)
		}
		return output, fmt.Errorf("agent failed: %s: %w", strings.TrimSpace(stderr.String()), err)
	}

	return output, nil
}

// RunTrailByID executes a trail by its ID.
func (r *Runner) RunTrailByID(ctx context.Context, id TrailID) (RunResult, error) {
	trail, err := r.store.Get(ctx, id)
	if err != nil {
		return RunResult{}, fmt.Errorf("failed to get trail: %w", err)
	}
	if trail == nil {
		return RunResult{}, fmt.Errorf("trail not found: %s", id)
	}

	return r.RunTrail(ctx, trail), nil
}

