func (r *Runner) runValidation(ctx context.Context, worktreePath string) (bool, string, error) {
	// Create context with timeout for validation (10 minutes)
	ctx, cancel := context.WithTimeout(ctx, 10*time.Minute)
	defer cancel()

	// Check settings for local_dev mode
	var cmd *exec.Cmd
	if s, err := settings.Load(); err == nil && s.LocalDev {
		// Use "go run ./cmd/entire" for local development
		// This assumes we're running from the CLI repo root
		cmd = exec.CommandContext(ctx, "go", "run", filepath.Join(r.repoRoot, "cmd/entire"), "validate", "--json")
