func getBranchInfo(repo *git.Repository) (current, defaultBr string, all []string) {
	// Get current branch
	head, err := repo.Head()
	if err == nil && head.Name().IsBranch() {
		current = head.Name().Short()
	} else {
		current = "HEAD"
	}

	// Get all branches
	branches, err := repo.Branches()
	if err == nil {
