			all = append(all, name)
			return nil
		})
	}

	// Determine default branch (prefer main, then master)
	defaultBr = "main"
	for _, b := range all {
		if b == "main" {
			defaultBr = "main"
			break
		}
		if b == "master" {
			defaultBr = "master"
		}
	}

	return current, defaultBr, all
}

