// getBranchInfo returns current branch, default branch, and all branch names.
func getBranchInfo(repo *git.Repository) (current, defaultBr string, all []string) {
	// Get current branch
	head, err := repo.Head()
	if err == nil && head.Name().IsBranch() {
		current = head.Name().Short()
	} else {
		current = "HEAD"
	}

	// Get all branches
	branches, err := repo.Branches()
	if err == nil {
		_ = branches.ForEach(func(ref *plumbing.Reference) error { //nolint:errcheck,gosec // Collecting branches best-effort; partial list is acceptable
			name := ref.Name().Short()
			all = append(all, name)
			return nil
		})
	}

	// Determine default branch from origin/HEAD
	defaultBr = getDefaultBranch(repo)

	return current, defaultBr, all
}

// getDefaultBranch returns the repository's default branch name.
// First tries to read origin/HEAD, then falls back to checking main/master.
func getDefaultBranch(repo *git.Repository) string {
	// Try to get the symbolic reference for origin/HEAD
	originHead, err := repo.Reference(plumbing.ReferenceName("refs/remotes/origin/HEAD"), true)
	if err == nil {
		// Extract branch name from refs/remotes/origin/main
		name := originHead.Name().Short()
		// name will be "origin/main" or "origin/master", extract the last part
		parts := strings.Split(name, "/")
		if len(parts) > 0 {
			return parts[len(parts)-1]
		}
	}

	// Fall back to checking common default branch names
	for _, branch := range []string{"main", "master"} {
		_, err := repo.Reference(plumbing.NewBranchReferenceName(branch), true)
		if err == nil {
			return branch
		}
	}

	return "main" // Ultimate fallback
}

