// First tries to read origin/HEAD, then falls back to checking main/master.
func getDefaultBranch(repo *git.Repository) string {
	// Try to get the symbolic reference for origin/HEAD
	originHead, err := repo.Reference(plumbing.ReferenceName("refs/remotes/origin/HEAD"), true)
	if err == nil {
		// Extract branch name from refs/remotes/origin/main
		name := originHead.Name().Short()
		// name will be "origin/main" or "origin/master", extract the last part
		parts := strings.Split(name, "/")
		if len(parts) > 0 {
			return parts[len(parts)-1]
		}
	}

	// Fall back to checking common default branch names
	for _, branch := range []string{branchMain, branchMaster} {
		_, err := repo.Reference(plumbing.NewBranchReferenceName(branch), true)
		if err == nil {
			return branch
		}
	}

	return branchMain // Ultimate fallback
}

